using System.Net;
using System.Text;
using Keynote.Core;
using Keynote.Midi;
using Keynote.Online;
using Keynote.Playback;
namespace Keynote.Tests;
public class AcquisitionWorkflowTests {
 sealed class Handler(byte[] bytes) : HttpMessageHandler { public bool Bad; protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token) { token.ThrowIfCancellationRequested(); return Task.FromResult(request.RequestUri!.Query.Contains("action=search") ? new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("[{\"id\":42,\"name\":\"Fixture title\",\"notes\":\"two tracks\"}]",Encoding.UTF8,"application/json")} : new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(Bad?"bad data"u8.ToArray():bytes)}); } }
 static string Dir()=>Path.Combine(Path.GetTempPath(),"keynote-e2e-"+Guid.NewGuid().ToString("N"));
 [Fact] public async Task SearchDownloadInspectSelectAndPrepareRetainsMetadataAndEvents() { var dir=Dir(); try { var bytes=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-2-tracks-type-1.mid")); using var http=new HttpClient(new Handler(bytes)); var provider=new MidisssCatalogProvider(http); var library=new MidiLibraryService(dir,new MidiImporter()); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>{{"MIDIsss",provider}},new MidiDownloadService(http),library,new MidiImporter()); var search=await provider.SearchAsync("fixture",0,CancellationToken.None); var selected=Assert.Single(search.Results); var inspected=await workflow.DownloadAndInspectAsync(selected,null,CancellationToken.None); Assert.Equal(2,inspected.Inspection.Tracks.Count); Assert.Equal(64,inspected.Entry.Sha256.Length); var prepared=await workflow.PrepareAsync(inspected.Entry,new[]{1},CancellationToken.None); Assert.Equal("Fixture title",prepared.Song.Name); Assert.Equal("MIDIsss",prepared.Entry.Provider); Assert.Contains("educational",prepared.Entry.License); Assert.Single(prepared.Song.Tracks); Assert.Equal(1,prepared.Song.Tracks[0].Index); Assert.Equal(8,prepared.Song.Notes.Count()); var pitches=prepared.Song.Notes.Select(n=>n.Pitch).Distinct().ToArray(); var mapping=new KeyboardMapping{Keys=pitches.Select((pitch,i)=>(pitch,i)).ToDictionary(x=>x.pitch,x=>((char)('A'+x.i)).ToString())}; Assert.Equal(16,PlaybackEngine.BuildEvents(prepared.Song,mapping).Length); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task InvalidDownloadDoesNotCreateLibraryEntry() { var dir=Dir(); try { using var http=new HttpClient(new Handler(Array.Empty<byte>()){Bad=true}); var provider=new MidisssCatalogProvider(http); var library=new MidiLibraryService(dir,new MidiImporter()); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>{{"MIDIsss",provider}},new MidiDownloadService(http),library,new MidiImporter()); var item=new CatalogResult("MIDIsss","42","title","Unknown","","","https://midisss.com/"); await Assert.ThrowsAsync<InvalidDataException>(()=>workflow.DownloadAndInspectAsync(item,null,CancellationToken.None)); Assert.Empty(await library.ListAsync(CancellationToken.None)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task CancelledOperationCannotPrepareSongOrCreateEntry() { var dir=Dir(); try { var bytes=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid")); using var http=new HttpClient(new Handler(bytes)); var provider=new MidisssCatalogProvider(http); var library=new MidiLibraryService(dir,new MidiImporter()); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>{{"MIDIsss",provider}},new MidiDownloadService(http),library,new MidiImporter()); using var cts=new CancellationTokenSource(); cts.Cancel(); var item=new CatalogResult("MIDIsss","42","title","Unknown","","","https://midisss.com/"); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>workflow.DownloadAndInspectAsync(item,null,cts.Token)); Assert.Empty(await library.ListAsync(CancellationToken.None)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task InvalidTrackSelectionCannotPrepareSong() { var dir=Dir(); try { var bytes=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid")); var library=new MidiLibraryService(dir,new MidiImporter()); var item=new CatalogResult("MIDIsss","42","title","Unknown","","","https://midisss.com/"); var saved=await library.AddAsync(bytes,item,CancellationToken.None); using var http=new HttpClient(new Handler(bytes)); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>(),new MidiDownloadService(http),library,new MidiImporter()); await Assert.ThrowsAsync<InvalidDataException>(()=>workflow.PrepareAsync(saved.Entry,new[]{999},CancellationToken.None)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 sealed class BlockingImporter : IMidiImporter { public readonly ManualResetEventSlim Entered=new(); public readonly ManualResetEventSlim Continue=new(); public MidiSong Import(string path) { Entered.Set(); Continue.Wait(); return new MidiImporter().Import(path); } }
 [Fact] public async Task CancellationDuringValidationRemovesTemporaryFile() { var dir=Dir(); var blocker=new BlockingImporter(); try { var bytes=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid")); var library=new MidiLibraryService(dir,blocker); var item=new CatalogResult("MIDIsss","42","title","Unknown","","","https://midisss.com/"); using var cts=new CancellationTokenSource(); var task=library.AddAsync(bytes,item,cts.Token); Assert.True(await Task.Run(()=>blocker.Entered.Wait(TimeSpan.FromSeconds(3)))); cts.Cancel(); blocker.Continue.Set(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); Assert.Empty(Directory.EnumerateFiles(dir)); } finally { blocker.Continue.Set(); if(Directory.Exists(dir))Directory.Delete(dir,true); blocker.Entered.Dispose(); blocker.Continue.Dispose(); } }
 sealed class PathLibrary(string path) : IMidiLibraryService { public Task<(LibraryEntry Entry,bool Duplicate)> AddAsync(byte[] data,CatalogResult metadata,CancellationToken token)=>throw new NotSupportedException(); public Task<IReadOnlyList<LibraryEntry>> ListAsync(CancellationToken token)=>throw new NotSupportedException(); public Task<string> OpenAsync(LibraryEntry entry,CancellationToken token) { token.ThrowIfCancellationRequested(); return Task.FromResult(path); } public Task RemoveAsync(LibraryEntry entry,CancellationToken token)=>throw new NotSupportedException(); }
 [Fact] public async Task CancellationDuringPreparationDoesNotProducePlayerSong() { var blocker=new BlockingImporter(); try { var fixture=Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid"); var entry=new LibraryEntry(new string('a',64),"title","unknown","test","source","unknown",DateTimeOffset.UtcNow); using var http=new HttpClient(new Handler(Array.Empty<byte>())); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>(),new MidiDownloadService(http),new PathLibrary(fixture),blocker); using var cts=new CancellationTokenSource(); var task=workflow.PrepareAsync(entry,new[]{0},cts.Token); Assert.True(await Task.Run(()=>blocker.Entered.Wait(TimeSpan.FromSeconds(3)))); cts.Cancel(); blocker.Continue.Set(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); } finally { blocker.Continue.Set(); blocker.Entered.Dispose(); blocker.Continue.Dispose(); } }
 [Fact] public async Task BrokenInspectionDoesNotReturnPartialResult() { var dir=Dir(); Directory.CreateDirectory(dir); var path=Path.Combine(dir,"broken.mid"); try { await File.WriteAllTextAsync(path,"invalid"); var entry=new LibraryEntry(new string('a',64),"title","unknown","test","source","unknown",DateTimeOffset.UtcNow); using var http=new HttpClient(new Handler(Array.Empty<byte>())); var workflow=new AcquisitionWorkflow(new Dictionary<string,IMidiCatalogProvider>(),new MidiDownloadService(http),new PathLibrary(path),new MidiImporter()); await Assert.ThrowsAsync<InvalidDataException>(()=>workflow.InspectAsync(entry,CancellationToken.None)); } finally { Directory.Delete(dir,true); } }
 [Fact] public void TestPatternsRequireExplicitMappedPitchesAndProduceExpectedShapes() { var pitches=new[]{60,62,64,65,67}; var chord=PlaybackTestPatterns.Create(PlaybackTestKind.ThreeNoteChord,pitches); Assert.Equal(3,chord.Notes.Count()); Assert.All(chord.Notes,n=>Assert.Equal(TimeSpan.Zero,n.Start)); Assert.Equal(5,PlaybackTestPatterns.Create(PlaybackTestKind.FiveNoteMelody,pitches).Notes.Count()); Assert.Throws<InvalidOperationException>(()=>PlaybackTestPatterns.Create(PlaybackTestKind.FiveNoteMelody,new[]{60})); Assert.Equal(TimeSpan.FromSeconds(15),PlaybackTestPatterns.Create(PlaybackTestKind.EmergencyStop,pitches).Duration); }
}
